"""Generate figures and research summary from saved Experiment 4 results."""
import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'outputs/experiment4'; FIG=OUT/'figures'; FIG.mkdir(exist_ok=True)
r=json.loads((OUT/'metrics.json').read_text()); names=list(r['models']); labels=['A','B','C','B1','B2','B3*','T0','T1','T2']; targets=['x position','y position','x velocity','y velocity']; colors=['#3275a1','#e28438']; plt.rcParams.update({'font.size':10,'figure.dpi':150,'savefig.dpi':200,'axes.spines.top':False,'axes.spines.right':False})
def vectors(name,mode='pooled',split='test'):
 e=r['models'][name]['representations'][mode]; return np.array(e['linear'][split]['r2']),np.array([a['metrics'][split]['r2'] for a in e['mlp']])
def save(fig,name): fig.tight_layout(); fig.savefig(FIG/name,bbox_inches='tight'); plt.close(fig)
fig,axs=plt.subplots(2,2,figsize=(12,7),sharex=True)
for j,ax in enumerate(axs.flat):
 x=np.arange(len(names)); l=np.array([vectors(n)[0][j] for n in names]); m=np.array([vectors(n)[1][:,j].mean() for n in names]); sd=np.array([vectors(n)[1][:,j].std() for n in names]); ax.bar(x-.2,l,.4,label='Ridge',color=colors[0]);ax.bar(x+.2,m,.4,yerr=sd,capsize=2,label='MLP',color=colors[1]); ax.axhline(0,color='black',lw=.7);ax.set_title(targets[j]);ax.set_ylabel('Test R²');ax.set_xticks(x,labels); ax.grid(axis='y',alpha=.2)
axs[0,0].legend();fig.suptitle('Frozen JEPA: linear and nonlinear probes (error bars: probe seed SD)');save(fig,'linear_vs_nonlinear.png')
fig,axs=plt.subplots(1,2,figsize=(11,4.5),sharey=True)
for k,ax in enumerate(axs):
 x=np.arange(len(names)); vals=np.array([vectors(n)[1][:,2*k:2*k+2].mean() for n in names]);ax.bar(x,vals,color=colors[1]); p='pixel_single' if k==0 else 'pixel_four'; ref=np.mean(r['baselines'][p]['test']['r2'][2*k:2*k+2]); ax.axhline(ref,color=colors[0],ls='--',label='Pixel ridge reference');ax.axhline(0,color='black',lw=.7);ax.set_title(['Position','Velocity (four-frame pixel reference)'][k]);ax.set_ylabel('Mean test R²');ax.set_xticks(x,labels);ax.legend(fontsize=8)
fig.suptitle('Physical-state recoverability (B3* is supervised)');save(fig,'physical_state_recoverability.png')
fig,axs=plt.subplots(2,2,figsize=(8,8))
for j,ax in enumerate(axs.flat):
 a=np.load(OUT/'full_b_pooled_predictions.npz'); y=a['y'][:,j]; p=a['mlp'][:,j]; ax.scatter(y,p,s=8,alpha=.45,color=colors[1]); lo=min(y.min(),p.min());hi=max(y.max(),p.max());ax.plot([lo,hi],[lo,hi],color='black',ls='--',lw=1);ax.set_xlabel('Actual');ax.set_ylabel('Predicted');ax.set_title(targets[j])
fig.suptitle('B pooled MLP: held-out predictions (probe seed 11)');save(fig,'predicted_vs_actual.png')
fig,axs=plt.subplots(2,2,figsize=(12,7),sharex=True)
for j,ax in enumerate(axs.flat):
 x=np.arange(len(names)); tr=np.array([vectors(n,split='train')[1][:,j].mean() for n in names]);te=np.array([vectors(n)[1][:,j].mean() for n in names]);ax.bar(x-.2,tr,.4,color=colors[0],label='Train');ax.bar(x+.2,te,.4,color=colors[1],label='Test');ax.axhline(0,color='black',lw=.7);ax.set_title(targets[j]);ax.set_ylabel('R²');ax.set_xticks(x,labels)
axs[0,0].legend();fig.suptitle('MLP generalization across probe seeds');save(fig,'generalization_gaps.png')
slot=[n for n in names if 'flat' in r['models'][n]['representations']];fig,axs=plt.subplots(2,2,figsize=(11,7),sharex=True)
for j,ax in enumerate(axs.flat):
 x=np.arange(len(slot));p=[vectors(n)[1][:,j].mean() for n in slot];f=[vectors(n,'flat')[1][:,j].mean() for n in slot];ax.bar(x-.2,p,.4,color=colors[0],label='Mean slots');ax.bar(x+.2,f,.4,color=colors[1],label='Concatenated slots');ax.axhline(0,color='black',lw=.7);ax.set_title(targets[j]);ax.set_ylabel('Test R²');ax.set_xticks(x,[n.upper() for n in slot])
axs[0,0].legend();fig.suptitle('Slot aggregation (fixed learned-query ordering; B3 supervised)');save(fig,'representation_aggregation.png')
fig,axs=plt.subplots(1,3,figsize=(12,3.6))
for ax,n in zip(axs,['full_b','b2','t1']):
 a=r['models'][n]['representations']['pooled']['mlp'][0]; h=np.array(a['history']);ax.plot(h[:,0],label='Train');ax.plot(h[:,1],label='Validation');ax.axvline(a['best_epoch'],color='black',ls='--',lw=.8);ax.set_title(n.upper());ax.set_xlabel('Epoch');ax.set_ylabel('Standardized MSE');ax.legend()
fig.suptitle('Probe learning curves (seed 11)');save(fig,'learning_curves.png')
# Paired sequence bootstrap conditional on the fixed seed-11 fitted probes; no model selection.
rng=np.random.default_rng(2026); boot={}
for n in names:
 a=np.load(OUT/f'{n}_pooled_predictions.npz'); y=a['y']; l=a['linear']; p=a['mlp']; idx=rng.integers(0,len(y),size=(2000,len(y))); delta=[]
 for ix in idx:
  yy=y[ix];den=((yy-yy.mean(0))**2).sum(0); delta.append(((l[ix]-yy)**2-(p[ix]-yy)**2).sum(0)/den)
 boot[n]=np.quantile(delta,[.025,.975],axis=0).tolist()
(OUT/'bootstrap.json').write_text(json.dumps({'description':'2000 paired test-sequence bootstrap resamples, conditional on fixed seed-11 probes; descriptive, unadjusted for multiple comparisons', 'intervals':boot},indent=2))
lines=['# Experiment 4: nonlinear probes of frozen JEPA representations','','## Question and hypothesis','','Can modest nonlinear probes recover physical state when linear probes cannot? The hypothesis is that state information may be nonlinearly encoded and therefore more accessible to an MLP.','','## Protocol','','Preselected seed-42 checkpoints: full A, B and C (validation objective); B1, B2 and B3 (fixed final epoch); and T0, T1 and T2 (validation objective). B3 used simulator-state supervision in encoder training; all others were self-supervised. full B+I duplicates C and is excluded. Earlier investigations have already inspected these models on test data, so this is a follow-up on previously examined checkpoints, not an entirely pristine confirmatory study.','','Each split has 2,400/300/300 independent sequences. Simulator RNG seeds and sequence IDs are disjoint across splits. Each sample is frame 3 and the matching same-step ball state; intervention groups refer to transition 2→3. The encoder receives only pixels, is in evaluation mode, and is frozen with no gradients; parameter hashes are unchanged. A and framewise B/C/B1/B2/B3/T0 use frame 3; T1/T2 use frames 0–3, matching training context. The simulator has one ball, selected by named state keys. No learned slot is identified as a ball. Mean slots is permutation invariant; flattened slots preserve learned query order and are permutation sensitive.','','Ridge uses the prior train-standardized input procedure and alpha 100. The two-hidden-layer 128/64 GELU MLP uses AdamW, training-only feature/target means and standard deviations, and standardized target MSE. Validation loss selects its epoch; the test set is used only after selection. Three probe seeds are reported as mean ± population SD. Pixel ridge uses alpha 1000 and pooled 8×8 RGB inputs; single-frame and four-frame history references use the same sequences and targets. See config.json for exact settings. Tiny-batch MSE: %.3g → %.3g.'%(r['sanity']['initial_mse'],r['sanity']['final_mse']),'', 'A separate fixed batch of 32 real training representations and targets reduced standardized MSE from %.3g to %.3g.' % (r['sanity']['real_training_batch']['initial_mse'],r['sanity']['real_training_batch']['final_mse']), '', '## Results','','R² is computed as 1 − SSE / target-centered SST per split; MSE and MAE are in simulator physical units in metrics.json. Negative R² is worse than the split-mean predictor.','', '| Model | Ridge x, y, vx, vy | MLP mean ± SD x, y, vx, vy |', '|---|---|---|']
for n in names:
 l,m=vectors(n); lines.append('| %s | %s | %s |'%(n,', '.join(f'{z:.3f}' for z in l),', '.join(f'{a:.3f} ± {b:.3f}' for a,b in zip(m.mean(0),m.std(0)))))
for k in ['constant','pixel_single','pixel_four']:
 lines.append('| %s | %s | — |'%(k,', '.join(f'{x:.3f}' for x in r['baselines'][k]['test']['r2'])))
lines+=['', 'The pooled MLP improves position for B and C and especially B1 y: B1 y rises from %.3f to %.3f R². Its flattened slots reach %.3f versus %.3f for flattened ridge. Four-frame pixel ridge scores %.3f / %.3f for position and %.3f / %.3f for velocity; the framewise single-pixel reference scores %.3f / %.3f for position. T1 and T2 pooled MLP velocity scores remain negative. This supports outcome D: some position is recoverable nonlinearly in certain encoders, with little generalizable velocity under these probes.' % (vectors('b1')[0][1],vectors('b1')[1][:,1].mean(),vectors('b1','flat')[1][:,1].mean(),vectors('b1','flat')[0][1],*r['baselines']['pixel_four']['test']['r2'],*r['baselines']['pixel_single']['test']['r2'][:2]), '', 'For seed 11, paired test-sequence bootstrap intervals for the MLP-minus-ridge gain exclude zero for both positions in B and C and for B1 y, conditional on the fixed probes; these are unadjusted exploratory intervals after prior test inspection. They do not establish a population-wide or multiple-comparison-corrected effect. The three probe seeds measure optimization variability, not independent model or dataset replications.', '', 'The pooled B MLP averages train/test R² of %.3f/%.3f for x and %.3f/%.3f for y: some gap, but no evidence of wholesale memorization. Several other models have near-zero training scores, suggesting underfitting or weak accessible signal rather than a memorization-dominated outcome. Predicted standard deviations for B2 are much smaller than target variation (see metrics.json), consistent with output collapse. Training loss curves, validation R², and train–test gaps provide the corresponding diagnostics.' % (vectors('full_b',split='train')[1][:,0].mean(),vectors('full_b')[1][:,0].mean(),vectors('full_b',split='train')[1][:,1].mean(),vectors('full_b')[1][:,1].mean()), '', 'Train, validation, test, intervention and non-intervention metrics, all per-seed curves, output standard deviations and the full concatenated-slot results are stored in metrics.json. Test subset counts: '+str(r['subgroup_counts'])+'. The bootstrap.json intervals are paired sequence resamples for the first fixed probe seed, conditional on the trained models; they are descriptive and not adjusted for multiple comparisons. Probe-seed standard deviations are not confidence intervals over encoder training or datasets.','','## Interpretation and limitations','','These are short-trained, small models with one selected encoder seed per family. Compare train and test scores and output standard deviations before interpreting low scores: an MLP may collapse toward its training mean or fit training samples without generalizing. A low frozen-probe score establishes only that the tested readouts, given these data and training settings, could not reliably recover the target; it does not prove the information is absent. The supervised B3 encoder is not evidence about purely self-supervised learning. The fixed-query slot flattening can exploit query ordering but does not establish persistent object identity. Intervention subsets are observational, not causal effects.','','Earlier Experiment 2 scores pooled all four frames and Experiment 3 scores frame 3; therefore the new matched single-frame scores are not directly interchangeable with all older scores. The earlier pixel reference pooled frames 1–3; this experiment uses exactly frame 3. The two-frame pixel reference and four-frame pixel reference use their indicated histories, and temporal JEPA comparisons should use the latter. Low velocity recoverability can also reflect limited information in the observed history, collisions, and interventions.','','For the article, distinguish predictive success from a demonstration of physical understanding, and state exactly which probes, data, and models support the claim. Neither frozen-probe failure nor a nonlinear gain alone establishes the absence or presence of a general causal world model.','','## Reproduction','','Run `.venv/bin/python scripts/experiment4.py` and `.venv/bin/python scripts/experiment4_pixel_four.py`, then `.venv/bin/python scripts/experiment4_aggregate.py` and `.venv/bin/python scripts/plot_experiment4.py`. Results and cached representations remain in outputs/experiment4; checkpoint and encoder hashes are recorded.']
(OUT/'nonlinear_probe_summary.md').write_text('\n'.join(lines)+'\n')
